// Codificación por repetición (run-length): «cantidad + símbolo» en lugar de repetir el símbolo
function comprimirRL(texto) {
  let salida = "";
  for (let i = 0; i < texto.length; ) {
    let j = i;
    while (j < texto.length && texto[j] === texto[i]) j++;
    salida += (j - i) + texto[i];
    i = j;
  }
  return salida;
}

function descomprimirRL(codigo) {
  let salida = "";
  for (const [, cantidad, simbolo] of codigo.matchAll(/(\d+)(\D)/g)) {
    salida += simbolo.repeat(Number(cantidad));
  }
  return salida;
}

// (esta versión simple supone que el texto original no tiene dígitos)
for (const original of ["BBBBBBBBBBBBNNNBBBBBBBBBBBBBB", "ABCD", "AAAAAAAAAAAAAAAAAAAA"]) {
  const codigo = comprimirRL(original);
  const vuelta = descomprimirRL(codigo);
  console.log(`${original}  →  ${codigo}  (${original.length} → ${codigo.length} caracteres, idéntico al volver: ${vuelta === original})`);
}

// Huffman: contar frecuencias, unir los dos más livianos hasta tener un solo árbol, leer los códigos
function construir(texto) {
  const frec = new Map();
  for (const c of texto) frec.set(c, (frec.get(c) || 0) + 1);

  let nodos = [...frec].map(([simbolo, peso]) => ({ simbolo, peso }));
  while (nodos.length > 1) {
    nodos.sort((a, b) => a.peso - b.peso);          // ordenar por peso (estable)
    const [izq, der] = nodos.splice(0, 2);           // los dos más livianos
    nodos.push({ peso: izq.peso + der.peso, izq, der });
  }

  const tabla = {};
  (function recorrer(nodo, prefijo) {
    if (nodo.simbolo !== undefined) { tabla[nodo.simbolo] = prefijo || "0"; return; }
    recorrer(nodo.izq, prefijo + "0");
    recorrer(nodo.der, prefijo + "1");
  })(nodos[0], "");
  return { frec, tabla, raiz: nodos[0] };
}

function codificar(texto, tabla) { return [...texto].map((c) => tabla[c]).join(""); }

function decodificar(bits, raiz) {
  let salida = "", nodo = raiz;
  for (const b of bits) {
    nodo = b === "0" ? nodo.izq : nodo.der;
    if (nodo.simbolo !== undefined) { salida += nodo.simbolo; nodo = raiz; }
  }
  return salida;
}

function probar(texto) {
  const { frec, tabla, raiz } = construir(texto);
  const bits = codificar(texto, tabla);
  console.log(`Mensaje: ${texto}`);
  for (const [s, f] of [...frec].sort((a, b) => b[1] - a[1])) console.log(`  ${s}  × ${f}  →  ${tabla[s]}`);
  const fijo = Math.ceil(Math.log2(frec.size));
  console.log(`  Huffman: ${bits.length} bits | ${fijo} bits fijos por símbolo: ${texto.length * fijo} | 8 bits por letra: ${texto.length * 8}`);
  console.log(`  Se recupera igual: ${decodificar(bits, raiz) === texto}\n`);
}

probar("AAAAAAAABBBBCCDE");
probar("ABRACADABRA");
probar("EL CAMION SALE EL CAMION LLEGA");
